package main

import (
	"cmp"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"time"

	"example.com/roombook/internal/api"
)

func main() {
	if err := run(os.Getenv, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(getenv func(string) string, stdout io.Writer) error {
	host := cmp.Or(getenv("HOST"), "127.0.0.1")
	port := cmp.Or(getenv("PORT"), "8080")

	ln, err := net.Listen("tcp", net.JoinHostPort(host, port))
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           api.NewHandler(),
		ReadHeaderTimeout: 5 * time.Second,
	}
	fmt.Fprintf(stdout, "Roombook API listening on http://%s\n", ln.Addr())
	return srv.Serve(ln)
}

package main

import (
	"cmp"
	"fmt"
	"log"
	"net/http"
	"os"
	"time"
)

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprintln(w, `{"status":"ok"}`)
	})
	mux.HandleFunc("GET /busy", func(w http.ResponseWriter, r *http.Request) {
		end := time.Now().Add(2 * time.Second)
		for time.Now().Before(end) {
			// two seconds of computing, with no waiting
		}
		fmt.Fprintln(w, `{"done":true}`)
	})
	addr := "127.0.0.1:" + cmp.Or(os.Getenv("PORT"), "8080")
	log.Fatal(http.ListenAndServe(addr, mux))
}
